test('missing amount', () => assert.throws(() => validateAmount(null)));

test('zero amount', () => assert.equal(validateAmount(0), 0));

test('omitted amount', () => assert.throws(() => validateAmount(), /invalid amount/));

for (const [label, amount] of [
  ['undefined', undefined],
  ['NaN', NaN],
  ['positive infinity', Infinity],
  ['negative infinity', -Infinity],
  ['negative number', -1],
  ['zero string', '0'],
  ['positive string', '12'],
  ['empty string', ''],
]) {
  test(`rejects ${label}`, () => assert.throws(() => validateAmount(amount), /invalid amount/));
}

