exports.cancel = (order, release) => {
  if (order.status === 'cancelled') {
    return order;
  }
  if (order.status !== 'pending') {
    throw new Error(`Cannot cancel order with status: ${order.status}`);
  }
  release(order.sku, order.quantity);
  order.status = 'cancelled';
  return order;
};

artifacts.orders.test.cjs:
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { cancel } = require('./orders.cjs');
test('cancel pending order', () => {
  const order = {status:'pending', sku:'SKU-1', quantity:2};
  const releases = [];
  const result = cancel(order, (sku, quantity) => { releases.push([sku, quantity]); });
  assert.strictEqual(result, order);
  assert.equal(order.status, 'cancelled');
  assert.deepEqual(releases, [['SKU-1', 2]]);
});

test('repeated cancellation returns the current order without releasing again', () => {
  const order = {status:'pending', sku:'SKU-1', quantity:2};
  let releaseCount = 0;
  const release = () => { releaseCount += 1; };

  cancel(order, release);
  assert.strictEqual(cancel(order, release), order);
  assert.strictEqual(cancel(order, release), order);
  assert.equal(order.status, 'cancelled');
  assert.equal(releaseCount, 1);
});

test('an already cancelled order returns without releasing inventory', () => {
  const order = {status:'cancelled', sku:'SKU-1', quantity:2};
  assert.strictEqual(cancel(order, () => assert.fail('must not release inventory')), order);
  assert.equal(order.status, 'cancelled');
});

test('a shipped order is rejected without releasing inventory or changing status', () => {
  const order = {status:'shipped', sku:'SKU-1', quantity:2};
  let releaseCount = 0;
  assert.throws(() => cancel(order, () => { releaseCount += 1; }));
  assert.equal(order.status, 'shipped');
  assert.equal(releaseCount, 0);
});

test('only pending orders can initiate cancellation', () => {
  const order = {status:'unknown', sku:'SKU-1', quantity:2};
  let releaseCount = 0;
  assert.throws(() => cancel(order, () => { releaseCount += 1; }));
  assert.equal(order.status, 'unknown');
  assert.equal(releaseCount, 0);
});

test('inventory release failure leaves the order pending and allows retry', () => {
  const order = {status:'pending', sku:'SKU-1', quantity:2};
  const failure = new Error('inventory release failed');
  assert.throws(() => cancel(order, () => { throw failure; }), error => error === failure);
  assert.equal(order.status, 'pending');

  let released = 0;
  assert.strictEqual(cancel(order, (sku, quantity) => { released += quantity; }), order);
  assert.equal(order.status, 'cancelled');
  assert.equal(released, 2);
});

