const { test } = require('node:test');
const assert = require('node:assert/strict');
const { cancel } = require('./orders.cjs');
test('cancel pending order', () => {
  const order = {status:'pending', sku:'SKU-1', quantity:2};
  const releases = [];
  const result = cancel(order, (sku, quantity) => { releases.push([sku, quantity]); });
  assert.strictEqual(result, order);
  assert.equal(order.status, 'cancelled');
  assert.deepEqual(releases, [['SKU-1', 2]]);
});

test('repeated cancellation releases inventory only once', () => {
  const order = {status:'pending', sku:'SKU-1', quantity:2};
  let releaseCalls = 0;
  const release = () => { releaseCalls += 1; };

  assert.strictEqual(cancel(order, release), order);
  assert.strictEqual(cancel(order, release), order);
  assert.strictEqual(cancel(order, release), order);
  assert.equal(order.status, 'cancelled');
  assert.equal(releaseCalls, 1);
});

test('already cancelled order is returned without releasing inventory', () => {
  const order = {status:'cancelled', sku:'SKU-1', quantity:2};
  const before = {...order};

  const result = cancel(order, () => { assert.fail('must not release inventory'); });

  assert.strictEqual(result, order);
  assert.deepEqual(order, before);
});

test('shipped order is rejected without releasing inventory or changing the order', () => {
  const order = {status:'shipped', sku:'SKU-1', quantity:2};
  const before = {...order};
  let releaseCalls = 0;

  assert.throws(() => cancel(order, () => { releaseCalls += 1; }));

  assert.equal(releaseCalls, 0);
  assert.deepEqual(order, before);
});

test('unsupported order status is rejected without releasing inventory', () => {
  const order = {status:'unknown', sku:'SKU-1', quantity:2};
  const before = {...order};
  let releaseCalls = 0;

  assert.throws(() => cancel(order, () => { releaseCalls += 1; }));

  assert.equal(releaseCalls, 0);
  assert.deepEqual(order, before);
});

test('failed release leaves the order pending and permits a successful retry', () => {
  const order = {status:'pending', sku:'SKU-1', quantity:2};
  const before = {...order};
  const failure = new Error('inventory release failed');

  assert.throws(() => cancel(order, () => { throw failure; }), (error) => error === failure);
  assert.deepEqual(order, before);

  const releases = [];
  const release = (sku, quantity) => { releases.push([sku, quantity]); };
  assert.strictEqual(cancel(order, release), order);
  assert.strictEqual(cancel(order, release), order);
  assert.equal(order.status, 'cancelled');
  assert.deepEqual(releases, [['SKU-1', 2]]);
});
